import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"20、【觀】 坤下巽上","description":"橫渠易說 - 20、【觀】 坤下巽上","frontmatter":{"title":"20、【觀】 坤下巽上","description":"橫渠易說 - 20、【觀】 坤下巽上"},"headers":[],"relativePath":"classics/hengqu/022.md","filePath":"classics/hengqu/022.md"}'),l={name:"classics/hengqu/022.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_20、【觀】-坤下巽上" tabindex="-1">20、【觀】 坤下巽上 <a class="header-anchor" href="#_20、【觀】-坤下巽上" aria-label="Permalink to “20、【觀】 坤下巽上”">​</a></h1><p>盥求神而薦褻也。</p><h3 id="彖曰-大觀在上-順而巽-中正以觀天下。-觀盥而不薦-有孚顒若-下觀而化也。觀天之神道而四時不忒-聖人以神道設教而天下服矣。" tabindex="-1">彖曰：大觀在上，順而巽，中正以觀天下。“觀盥而不薦，有孚顒若”，下觀而化也。觀天之神道而四時不忒，聖人以神道設教而天下服矣。 <a class="header-anchor" href="#彖曰-大觀在上-順而巽-中正以觀天下。-觀盥而不薦-有孚顒若-下觀而化也。觀天之神道而四時不忒-聖人以神道設教而天下服矣。" aria-label="Permalink to “彖曰：大觀在上，順而巽，中正以觀天下。“觀盥而不薦，有孚顒若”，下觀而化也。觀天之神道而四時不忒，聖人以神道設教而天下服矣。”">​</a></h3><h3 id="象曰-風行地上-觀-先王以省方觀民設教。" tabindex="-1">象曰：風行地上，觀，先王以省方觀民設教。 <a class="header-anchor" href="#象曰-風行地上-觀-先王以省方觀民設教。" aria-label="Permalink to “象曰：風行地上，觀，先王以省方觀民設教。”">​</a></h3><p>內順外巽，示民以順而外從巽，此祭所以為教之本，故盥而不薦。“中正以觀天下”，又曰“大觀在上”，皆謂五也，凡言“觀我生”，亦皆謂五也。天不言，藏其用而四時行。神道，如“盥而不薦”之類，盥簡潔而神，薦褻近而煩也。 有兩則須有感，然天之感有何思慮？莫非自然。聖人則能用感，何謂用感？凡教化設施，皆是用感也，作於此化於彼者，皆感之道，聖人以神道設教是也。 天不言而四時行，聖人［神道］設教而天下服，誠於此，動於彼，神之道歟!</p><h3 id="初六-童觀-小人無咎-君子吝。-象曰-初六童觀-小人道也。" tabindex="-1">初六，童觀，小人無咎，君子吝。 象曰：“初六童觀”，小人道也。 <a class="header-anchor" href="#初六-童觀-小人無咎-君子吝。-象曰-初六童觀-小人道也。" aria-label="Permalink to “初六，童觀，小人無咎，君子吝。 象曰：“初六童觀”，小人道也。”">​</a></h3><p>所觀者末，小人之道，施於君子則吝。</p><h3 id="六二-窺觀-利女貞。-象曰-窺觀女貞-亦可醜也。" tabindex="-1">六二，窺觀，利女貞。 象曰：“窺觀女貞”，亦可醜也。 <a class="header-anchor" href="#六二-窺觀-利女貞。-象曰-窺觀女貞-亦可醜也。" aria-label="Permalink to “六二，窺觀，利女貞。 象曰：“窺觀女貞”，亦可醜也。”">​</a></h3><p>得婦人之道，雖正可羞。</p><h3 id="六三-觀我生進退。-象曰-觀我生進退-未失道也。" tabindex="-1">六三，觀我生進退。 象曰：“觀我生進退”，未失道也。 <a class="header-anchor" href="#六三-觀我生進退。-象曰-觀我生進退-未失道也。" aria-label="Permalink to “六三，觀我生進退。 象曰：“觀我生進退”，未失道也。”">​</a></h3><p>觀上所施而進退，雖以陰居陽，於道未失，以其在下卦之體而應於上，故曰“進退”。</p><h3 id="六四-觀國之光-利用賓於王。-象曰-觀國之光-尚賓也。" tabindex="-1">六四，觀國之光，利用賓於王。 象曰：“觀國之光”，尚賓也。 <a class="header-anchor" href="#六四-觀國之光-利用賓於王。-象曰-觀國之光-尚賓也。" aria-label="Permalink to “六四，觀國之光，利用賓於王。 象曰：“觀國之光”，尚賓也。”">​</a></h3><p>體柔巽而以陰居下賓之，必無過也，故利。下一作陰。</p><h3 id="九五-觀我生-君子無咎。-象曰-觀我生-觀民也。" tabindex="-1">九五，觀我生，君子無咎。 象曰：“觀我生”，觀民也。 <a class="header-anchor" href="#九五-觀我生-君子無咎。-象曰-觀我生-觀民也。" aria-label="Permalink to “九五，觀我生，君子無咎。 象曰：“觀我生”，觀民也。”">​</a></h3><p>觀我所自出者。</p><h3 id="上九-觀其生-君子無咎。-象曰-觀其生-志未平也。" tabindex="-1">上九，觀其生，君子無咎。 象曰：“觀其生”，志未平也。 <a class="header-anchor" href="#上九-觀其生-君子無咎。-象曰-觀其生-志未平也。" aria-label="Permalink to “上九，觀其生，君子無咎。 象曰：“觀其生”，志未平也。”">​</a></h3><p>以剛陽極上之德，居不臣不任之位，以觀國家之政，志有所未平也，有君子循理之心則可免咎。俯視九五之為，故曰“觀其生”。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
